observation.command:
cd /workspace && docker exec -i sva-studio-postgres psql -U sva -d sva_studio <<'SQL'
-- What columns does _private_tasks have?
SELECT column_name FROM information_schema.columns WHERE table_schema='graphile_worker' AND table_name='_private_tasks' ORDER BY ordinal_position;
SQL
echo "=== test insert as worker ==="
docker exec -i sva-studio-postgres psql -v ON_ERROR_STOP=1 -U sva -d sva_studio <<'SQL' 2>&1 | head
SET ROLE sva_job_worker;
INSERT INTO graphile_worker._private_tasks (identifier) VALUES ('x') RETURNING id;
SQL
echo "=== test the claim CTE (add_job then claim) as worker ==="
docker exec -i sva-studio-postgres psql -U sva -d sva_studio <<'SQL' 2>&1 | head
SET ROLE sva_job_worker;
SELECT graphile_worker.add_job('studio_job_execute', '{}'::json, 'default', now(), 5, 'test-claim', 0, NULL, 'replace');
SQL
